import ballerina/io;

function d(int|string x) returns int {
    if x is int {
        return 1;
    } else if x is string {
        return 2;
    } else {
        boolean b = x;
        return b ? 3 : 4;
    }
}

function e(int|string x) returns int {
    if x is int && x is string {
        boolean b = x;
        return b ? 1 : 2;
    }
    return 0;
}

public function main() {
    io:println(d(3));
    io:println(e(3));
}

